function canvasContext(id,height=170){const c=$(id),w=c.clientWidth||600,dpr=Math.min(2,window.devicePixelRatio||1);if(c.width!==Math.round(w*dpr)||c.height!==height*dpr){c.width=Math.round(w*dpr);c.height=height*dpr}const g=c.getContext('2d');g.setTransform(dpr,0,0,dpr,0,0);g.clearRect(0,0,w,height);return{g,w,h:height}}
function drawScope(p){const{g,w,h}=canvasContext('scope');g.strokeStyle='#2e4035';g.lineWidth=1;for(let x=0;x<w;x+=w/10){g.beginPath();g.moveTo(x,0);g.lineTo(x,h);g.stroke()}for(let y=0;y<h;y+=28){g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke()}function path(color,fn){g.strokeStyle=color;g.beginPath();for(let x=0;x<w;x++){const y=fn(x/w*.04);x?g.lineTo(x,y):g.moveTo(x,y)}g.stroke()}if(!p.she&&!p.six)path('#788d7f',t=>43-28*PWM.triangle(t*p.fc));path('#c5ed88',t=>43-28*p.m*(Math.sin(TAU*t*p.f)+p.third*Math.sin(3*TAU*t*p.f)));path('#f1b47b',t=>130-(p.on?(PWM.phase(t*p.f,p,t*p.fc)-PWM.phase(t*p.f-1/3,p,t*p.fc))*14:0))}
let spectrumData=new Uint8Array(1024);function drawSpectrum(){const{g,w,h}=canvasContext('spectrum');g.strokeStyle='#2e4035';for(let y=20;y<h;y+=35){g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke()}if(!analyser||!audioEnabled){g.fillStyle='#819889';g.font='13px system-ui';g.fillText('启用声音后显示实时输出频谱',20,85);return}analyser.getByteFrequencyData(spectrumData);for(let x=0;x<w;x+=3){const lo=100*Math.pow(120,x/w),hi=100*Math.pow(120,(x+3)/w),b0=Math.floor(lo/ctx.sampleRate*2048),b1=Math.min(1023,Math.ceil(hi/ctx.sampleRate*2048));let level=0;for(let j=b0;j<=b1;j++)level=Math.max(level,spectrumData[j]||0);g.fillStyle=x<w*.6?'#c5ed88':'#f1b47b';g.fillRect(x,h-12-level/255*(h-24),2,level/255*(h-24))}}
function voltageEstimate(p){if(!p.on)return 0;if(p.she){let sum=0;for(let i=0;i<4096;i++){const x=(i+.5)/4096;sum+=PWM.phase(x,p,0)*Math.sin(TAU*x)}return sum*2/4096*1500*Math.sqrt(3)/(2*Math.sqrt(2));}if(p.six)return 1500*Math.sqrt(6)/Math.PI;let coeff=0;for(let i=0;i<96;i++){const a=(i+.5)*TAU/96;coeff+=clamp(p.m*(Math.sin(a)+p.third*Math.sin(3*a)),-1,1)*Math.sin(a)}return coeff*2/96*1500*Math.sqrt(3)/(2*Math.sqrt(2))}
function render(p){$('speed').textContent=v.toFixed(1);$('freq').textContent=p.f.toFixed(1)+' Hz';$('rpm').textContent=Math.round(p.rpm)+' rpm';$('carrier').textContent=!p.on?'—':Math.round(p.fc)+' Hz';$('volt').textContent=Math.round(voltageEstimate(p))+' V';$('slipLabel').textContent='滑差 '+(p.slip>=0?'+':'')+p.slip.toFixed(2)+' Hz';$('distance').textContent=distance<1000?Math.round(distance)+' m':(distance/1000).toFixed(2)+' km';const stage=!p.on?'逆变器关闭':p.six?'六步波':p.she?'SHE '+p.n+' 脉冲':p.n?'同步 '+p.n+' 脉冲':'异步 PWM';$('stage').textContent=stage;$('status').textContent='● '+(v<.02?'停车':({traction:'牵引',hold:'保持',coast:'惰行',brake:'再生制动'})[p.drive]);$('scrub').value=v;$('rail').style.backgroundPosition=railOffset+'px 0';$('profileNote').textContent=p.train.drive+' · '+p.pr.label+'。车型参考，非精确复刻。';$('schedule').textContent='当前方向：'+(p.drive==='brake'?'制动':'牵引 / 保持')+'；演示切换点 '+p.points.map(x=>x.toFixed(1)+' Hz').join(' / ')+'；同步频率比 '+p.pr.ns.join(' → ')+' → 六步波。';if(p.program==='alstom'){$('profileNote').textContent='Alstom 社区参考程序 · 未确认具体上海车型；车型标签不改变此程序。';$('schedule').textContent='公开 YAML 参考：'+(gpsActive?'GPS 连续跟随，升降速共用牵引曲线；不是实车制动程序。':p.drive==='brake'?'制动；15 Hz 以下无定义，本页关闭输出。':'牵引 / 保持。')+' 切换点：'+p.points.join(' / ')+' Hz。使用原始 SHE 角度表；下方载波 / 切换倍率仅对演示模板生效。';}const cfg=vehicle();$('formula').textContent=`${v.toFixed(1)} km/h → ${p.rpm.toFixed(0)} rpm → ${p.rotorHz.toFixed(2)} + (${p.slip.toFixed(2)}) = ${p.referenceF.toFixed(2)} Hz${p.on?'':'（机械等效；逆变器输出 0 Hz）'}  |  D=${(cfg.D*1000).toFixed(0)} mm · G=${cfg.G.toFixed(2)} · P=${cfg.P}`;$('audioStatus').textContent=audioEnabled&&gpsActive&&gpsCoasting?'惰行 · 牵引已静音':audioEnabled?$('sound').value==='motor'?'电机声 · '+({dry:'干声',cabin:'车厢',tunnel:'隧道'})[$('environment').value]:'电磁拾音 · 无声学混响':'声音未启用';drawScope(p);drawSpectrum()}
function frame(now){const dt=clamp((now-last)/1000,0,.1);last=now;step(dt);const p=config();if(node&&now-lastMessage>=40){lastMessage=now;const{f,fc,n,six,m,on,load,random,third,voice,speed,she}=p;node.port.postMessage({f,fc,n,six,m,on,load,random,third,voice,speed,she,gps:gpsActive});master.gain.setTargetAtTime(audioEnabled&&(!gpsActive||(gpsSignal&&!gpsCoasting))?numeric('volume',0,70,20)/100:0,ctx.currentTime,.04);const motor=$('sound').value==='motor';if(wetGain&&!roomChanging)wetGain.gain.setTargetAtTime(desiredWet(),ctx.currentTime,.08);motorGain.gain.setTargetAtTime(motor?1:0,ctx.currentTime,.06);coilGain.gain.setTargetAtTime(motor?0:.45,ctx.currentTime,.06);filters.forEach((b,i)=>b.frequency.setTargetAtTime(p.pr.res[i],ctx.currentTime,.1))}if(now-lastDisplay>=33){lastDisplay=now;render(p);updateButtons()}requestAnimationFrame(frame)}
updateLabels();updateButtons();requestAnimationFrame(frame);document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.hidden&&gpsActive)stopGPS('已离开前台，定位与声音已停止。点击启用 GPS 可重新开始。');if(document.hidden&&ctx)ctx.suspend();else if(ctx&&audioEnabled)ctx.resume().catch(()=>{$('hint').textContent='点击声音按钮恢复音频。'})});
